        //        "matchRole":"TAKER"
        //     }
        //
        string? marketId = this.safeString(trade, "symbol");
        market = this.safeMarket(marketId, market);
        Int64? timestamp = this.safeInteger(trade, "createTime");
        string? takerMaker = this.safeStringLower2(trade, "matchRole", "taker");
        return this.safeTrade(new Dictionary<string, object>() {
            { "info", trade },
            { "id", this.safeString2(trade, "id", "tradeId") },
            { "symbol", this.safeString(market, "symbol") },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "order", this.safeString(trade, "orderId") },
            { "type", this.safeStringLower(trade, "type") },
            { "side", this.safeStringLower2(trade, "takerSide", "side") },
            { "takerOrMaker", takerMaker },
            { "price", this.omitZero(this.safeString2(trade, "tradePrice", "price")) },
            { "amount", this.omitZero(this.safeString2(trade, "filledQuantity", "quantity")) },
            { "cost", this.safeString2(trade, "amount", "filledAmount") },
            { "fee", new Dictionary<string, object>() {
                { "rate", null },
                { "cost", this.safeString(trade, "tradeFee") },
                { "currency", this.safeString(trade, "feeCurrency") },
            } },
        }, market);
    }

    public virtual string? parseStatus(string? status)
    {
        Dictionary<string, object> statuses = new Dictionary<string, object>() {
            { "NEW", "open" },
            { "PARTIALLY_FILLED", "open" },
            { "FILLED", "closed" },
            { "PENDING_CANCEL", "open" },
            { "PARTIALLY_CANCELED", "open" },
            { "CANCELED", "canceled" },
        };
        return this.safeString(statuses, status, status);
    }

